<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$_SERVER['REQUEST_METHOD']='CLI';require_once __DIR__.'/../config/db.php';$conn=db();$failed=false;
$checks=['configuration ranges'=>"SELECT COUNT(*) n FROM erp_contribution_configs WHERE rate NOT BETWEEN 0 AND 100 OR(effective_to IS NOT NULL AND effective_to<effective_from)",'period formulas'=>"SELECT COUNT(*) n FROM erp_contribution_periods WHERE basis_amount<0 OR rate NOT BETWEEN 0 AND 100 OR ABS(calculated_amount-ROUND(basis_amount*rate/100,3))>0.001",'configuration snapshots'=>"SELECT COUNT(*) n FROM erp_contribution_periods p JOIN erp_contribution_configs c ON c.id=p.config_id WHERE p.user_id<>c.user_id OR p.contribution<>c.contribution OR p.period_start<c.effective_from OR(c.effective_to IS NOT NULL AND p.period_start>c.effective_to)"];
foreach($checks as $label=>$sql){$n=(int)$conn->query($sql)->fetch_assoc()['n'];if($n){$failed=true;fwrite(STDERR,"FAIL $label: $n mismatch(es)\n");}else echo "PASS $label reconciles\n";}exit($failed?1:0);
